Lemma PMutex_cells : forall m M lk, PMutex m M lk ->
  rw_cells usegs m M [CB 4 [b8 0; b8 0; b8 0; b8 0]; C4 (wz lk);
                      CB 32 [b8 0; b8 0; b8 0; b8 0; b8 0; b8 0; b8 0; b8 0; b8 0; b8 0; b8 0; b8 0; b8 0; b8 0; b8 0; b8 0;
                             b8 0; b8 0; b8 0; b8 0; b8 0; b8 0; b8 0; b8 0; b8 0; b8 0; b8 0; b8 0; b8 0; b8 0; b8 0; b8 0]]
  /\ (lk = 0 \/ lk = EBUSY) /\ M mod 4 = 0.
Proof. intros m M lk [PM [LK AL]]. unfold PMutexCells, zeros in PM. cbn [repeat] in PM. auto. Qed.

Lemma PMutex_fold : forall m M lk,
  rw_cells usegs m M [CB 4 [b8 0; b8 0; b8 0; b8 0]; C4 (wz lk);
                      CB 32 [b8 0; b8 0; b8 0; b8 0; b8 0; b8 0; b8 0; b8 0; b8 0; b8 0; b8 0; b8 0; b8 0; b8 0; b8 0; b8 0;
                             b8 0; b8 0; b8 0; b8 0; b8 0; b8 0; b8 0; b8 0; b8 0; b8 0; b8 0; b8 0; b8 0; b8 0; b8 0; b8 0]] ->
  (lk = 0 \/ lk = EBUSY) -> M mod 4 = 0 -> PMutex m M lk.
Proof. intros m M lk PM LK AL. split; [| split; [exact LK| exact AL]]. unfold PMutexCells, zeros. cbn [repeat]. exact PM. Qed.

Lemma amo_aligned_M4 : forall M, 0 <= M -> M + 8 <= 2^64 -> M mod 4 = 0 -> amo_aligned AW (Z_to_bv 64 (M + 4)) = true.
Proof. intros M H0 H1 AL. apply amo_aligned_intro; [lia|]. rewrite <- Zplus_mod_idemp_l, AL. reflexivity. Qed.

